<script setup>
import {computed,onMounted,ref} from 'vue';import {get,fmt,pct} from '../api/client';import MetricCard from '../components/MetricCard.vue';import DataTable from '../components/DataTable.vue';
const data=ref(null),error=ref(''),activeModel=ref('multi_factor_rank'),showBacktestHelp=ref(false);const modelNames={multi_factor_rank:'次日方向模型',tradeable_t1_open:'T+1可交易模型'};const model=computed(()=>data.value?.models?.[activeModel.value]||{latest_prediction:{},latest_intraday_groups:[]});onMounted(async()=>{try{data.value=await get('/dashboard')}catch(e){error.value=e.message}});
const cols=[{label:'分组',key:'top_n',format:v=>`Top${v}`},{label:'上涨比例',key:'up_rate',format:pct},{label:'平均收益',key:'avg_return',format:pct,class:v=>v>0?'positive':'negative'},{label:'市场收益',key:'market_avg_return',format:pct},{label:'超额收益',key:'excess_return',format:pct,class:v=>v>0?'positive':'negative'}];
</script><template><div v-if="error" class="empty">{{error}}</div><div v-else-if="!data" class="empty">加载中…</div><template v-else><div class="grid"><MetricCard label="股票数量" :value="fmt(data.stats.stock_count,0)" sub="SH · SZ · BJ"/><MetricCard label="日线记录" :value="fmt(data.stats.daily_count,0)" :sub="`${data.stats.first_date} — ${data.stats.latest_date}`"/><MetricCard label="预测批次" :value="data.stats.prediction_runs" sub="两套模型独立保存"/><MetricCard label="正式验证" :value="data.stats.verification_runs" sub="按模型分别验证"/></div><div class="model-tabs"><button v-for="(name,code) in modelNames" :class="{active:activeModel===code}" @click="activeModel=code">{{name}}</button></div><div class="model-scope-note">当前查看：<b>{{modelNames[activeModel]}}</b> · <template v-if="activeModel==='tradeable_t1_open'">下一交易日开盘买入，再下一交易日开盘卖出</template><template v-else>信号日收盘至下一交易日收盘</template></div><div class="section"><div class="detail-heading"><div><h2>{{modelNames[activeModel]}}历史回测表现</h2><span class="backtest-caption">历史样本计算，不是正式验证结果</span></div><button @click="showBacktestHelp=!showBacktestHelp">{{showBacktestHelp?'收起说明':'指标说明'}}</button></div><div v-if="showBacktestHelp" class="card logic-card backtest-help"><p><b>样本上涨率：</b>历史候选收益为正的比例；<b>候选平均：</b>候选平均收益；<b>市场平均：</b>同口径全市场平均收益；<b>样本超额：</b>候选平均减市场平均。</p><p>历史较短时可能偏乐观，正式结果请看“收盘验证”。</p></div><div class="grid backtest-grid"><MetricCard label="样本上涨率" :value="pct(model.latest_prediction.backtest_up_rate)"/><MetricCard label="候选平均" :value="pct(model.latest_prediction.backtest_avg_return)"/><MetricCard label="市场平均" :value="pct(model.latest_prediction.market_avg_return)"/><MetricCard label="样本超额" :value="pct(model.latest_prediction.excess_return)"/></div></div><div class="section"><h2>{{modelNames[activeModel]}}最新盘中表现</h2><DataTable :columns="cols" :rows="model.latest_intraday_groups"/></div></template></template>
